 const labels={safetyRestricted:'Rood/oranje in het officiële reisadvies; conservatief uitgesloten',safetyUnknown:'Reisadvies ontbreekt of is ouder dan 30 dagen',avoidCountry:'Land dat jullie liever overslaan',budget:x.delta!=null?`${money(x.delta)} boven budget per persoon`:'Kostenraming ontbreekt',minTemp:'Minimumtemperatuur',maxTemp:'Maximumtemperatuur',maxRain:'Maximale regenval',minSun:'Werkelijke zonneschijn',minDaylight:'Minimaal daglicht',heritageKind:'Geen locatie van het gekozen UNESCO-erfgoedtype in deze bronselectie',minHighlights:'Minder bevestigde erfgoedlocaties dan je minimum',directOnly:'Rechtstreekse vlucht niet bevestigd',maxStops:'Aantal overstappen',bestOnly:'Klimaatvenster (18–32 °C, ≤150 mm regen, ≥5 uur zon)',visited:'Al bezocht (land, regio of bovenliggende regio)',excludedCountry:'Uitgesloten op je eerdere keuze',overview:'Landsoverzicht of niet uitgewerkt vakantiegebied: kies een specifieke regio',region:'Buiten de gekozen wereldregio',type:'Dit bestemmingstype is niet aangevinkt',cityTrip:'Losse stedentrips worden vermeden',styles:'Andere reisvorm dan aangevinkt',maxFlightHours:x.value==null?'Tijd in het vliegtuig onbekend':`Vliegtijd ${value(x.value,' uur')} boven je limiet`,maxTravelHours:x.value==null?'Totale reistijd onbekend':`Totale reistijd ${value(x.value,' uur')} boven je limiet`,maxBoatMinutes:x.value==null?'Noodzakelijke bootduur onbekend':`Noodzakelijke bootrit ${value(x.value,' minuten')} boven je limiet`};
 return (labels[x.key]||x.key)+(Number.isFinite(x.value)&&['minTemp','maxTemp','maxRain','minSun'].includes(x.key)?` — ${x.value}${x.key.includes('Temp')?' °C':x.key==='maxRain'?' mm':' uur'}`:'')+(x.months?.length&&x.key!=='budget'?` (${x.months.map(m=>months[m-1]).join(', ')})`:'');
